// Получаем исходный ответ
const rawResponse = $json.text ?? "";

// Функция извлечения JSON из ответа
function extractJsonFromResponse(str) {
  if (!str || typeof str !== "string") return null;

  // Убираем Markdown-обрамление ```json ... ```
  const markdownMatch = str.match(/```(?:json)?\s*([\s\S]*?)```/i);

  if (markdownMatch) {
    return markdownMatch[1].trim();
  }

  // Сначала ищем JSON-объект
  const objectMatch = str.match(/\{[\s\S]*\}/);

  if (objectMatch) {
    return objectMatch[0].trim();
  }

  // Затем ищем JSON-массив
  const arrayMatch = str.match(/\[[\s\S]*\]/);

  if (arrayMatch) {
    return arrayMatch[0].trim();
  }

  return null;
}

// Парсим ответ
try {
  const cleaned = extractJsonFromResponse(rawResponse);

  if (!cleaned) {
    throw new Error("JSON не найден в ответе");
  }

  const parsed = JSON.parse(cleaned);

  // Проверяем структуру ответа
  if (!parsed || typeof parsed !== "object") {
    throw new Error("Некорректная структура JSON");
  }

  return {
    json: {
      ...$json,
      status_query_llm: true,
      type_llm: parsed.type ?? null,
      email_llm: parsed.email ?? null,
      parse_error: null
    }
  };

} catch (err) {
  return {
    json: {
      ...$json,
      status_query_llm: false,
      type_llm: null,
      email_llm: null,
      parse_error: err.message
    }
  };
}

